function GlassActionImages({ normal, hover, mask = false }) {
    const themed = mask && document.documentElement.classList.contains("pt-design-accent");
    const image = (url, variant, color) => {
        const className = "glass-button__icon glass-button__icon--" + variant;
        if (themed) {
            return C.jsx("span", { className, "aria-hidden": true, style: {
                backgroundColor: color,
                WebkitMask: 'url("' + url + '") center / contain no-repeat'
            } });
        }
        return C.jsx("img", { className, src: url, alt: "", "aria-hidden": true });
    };
    return C.jsxs(C.Fragment, { children: [
        image(normal, "default", "var(--pt-accent-text)"),
        image(hover, "hover", "rgb(var(--pt-accent-pale-rgb))")
    ] });
}

function SessionExitAction({ label, onClick, children }) {
    return C.jsxs("button", { type: "button", className: "pt-session-action", onClick, children: [
        C.jsx("span", { className: "pt-session-action__label", children: label }),
        C.jsx("span", { className: "glass-button pt-session-action__glyph", "aria-hidden": true, children })
    ] });
}

function At({ settingsLabel, supportLabel, quitLabel, disconnectLabel, onSettings, onSupport, onQuit, onDisconnect }) {
    const quitIcon = C.jsx(GlassActionImages, { normal: wt, hover: Ct });
    return C.jsxs("nav", { className: disconnectLabel ? "side-actions pt-session-actions" : "side-actions",
        "aria-label": "Quick actions", children: [
            C.jsx(kt, { label: settingsLabel, onClick: onSettings, children: C.jsx(GlassActionImages, { normal: Et, hover: Tt, mask: true }) }),
            C.jsx(kt, { label: supportLabel, onClick: onSupport, children: C.jsx(GlassActionImages, { normal: Ot, hover: Dt }) }),
            disconnectLabel ? C.jsxs(C.Fragment, { children: [
                C.jsx(SessionExitAction, { label: disconnectLabel, onClick: onDisconnect,
                    children: C.jsx(PTHubActionIcon, { action: "disconnect" }) }),
                C.jsx(SessionExitAction, { label: quitLabel, onClick: onQuit, children: quitIcon })
            ] }) : C.jsx(kt, { label: quitLabel, onClick: onQuit, children: quitIcon })
        ]
    });
}
